  "summary": "【热点名+中文】印尼TikTok创作者Noxa用AI造'Tung Tung Tung Sahur(通通通·沙胡尔)'木棍形象引爆'意大利脑腐(Italian Brainrot)'迷因，Roblox《Steal a Brainrot(偷脑腐)》峰值2539万同时在线。\n【热度信号】TikTok/YouTube Shorts千万级传播、Z世代亚文化奇观。\n【设计机会】木棍人、香蕉猩猩等混搭怪诞形象、'Brainrot'文字款；UGC迷因版权风险极低、非常适合搞怪图案。\n【时间窗口】2025-2026持续长热。\n【热度星级】★★★★（印选 11-08 热点重排上架：库内真实历史热点复用，非新研究。）",
